WITH customer_profit AS ( SELECT c.c_customer_id, c.c_first_name, c.c_last_name, SUM(ss.ss_net_profit) AS total_profit, SUM(ss.ss_net_paid) AS total_sales, COUNT(*) AS transaction_count, MAX(d.d_date) AS latest_purchase_date FROM store_sales ss JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk LEFT JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk WHERE d.d_year = year(current_date) - 1 GROUP BY c.c_customer_id, c.c_first_name, c.c_last_name ) SELECT c_customer_id, c_first_name, c_last_name, total_profit, total_sales, transaction_count, latest_purchase_date, CASE WHEN total_profit >= 100000 THEN 'Platinum' WHEN total_profit >= 50000 THEN 'Gold' WHEN total_profit >= 20000 THEN 'Silver' ELSE 'Bronze' END AS profit_tier, RANK() OVER (ORDER BY total_profit DESC) AS profit_rank, DENSE_RANK() OVER (ORDER BY transaction_count DESC) AS txn_dense_rank FROM customer_profit ORDER BY profit_rank LIMIT 10
